def md():
    head = "| المعرّف | المشكلة | الموقع | تحقُّق الملاحظة | الإجراء | نوع التعديل | الدليل | الحالة |\n|---|---|---|---|---|---|---|---|\n"
    body = "\n".join("| " + " | ".join(r) + " |" for r in ROWS)
    return ("# جدول تتبع المشكلات — المراجعة R2\n\n"
            "التاريخ: 28 أكتوبر 2026. الفرع: `claude/rem-thesis-revision-r2-j1px4f`. "
            "«تحقُّق الملاحظة» يبيّن هل كانت المشكلة قائمة فعلًا في النسخة الحالية قبل التعديل.\n\n"
            "**أنواع التعديل:** تحريري = صياغة فقط؛ برمجي = تصحيح خطأ في الكود؛ منهجي = يؤثر في التصميم أو التفسير؛ "
            "تحليل جديد/لاحق = تحليل أُضيف بعد رؤية النتائج.\n\n" + head + body + "\n")


def xlsx(path):
    import openpyxl
    from openpyxl.styles import Alignment, Font

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "التتبع"
    ws.sheet_view.rightToLeft = True
    ws.append(["المعرّف", "المشكلة", "الموقع", "تحقق الملاحظة", "الإجراء", "نوع التعديل", "الدليل", "الحالة"])
    for c in ws[1]:
        c.font = Font(bold=True)
    for r in ROWS:
        ws.append(list(r))
    for row in ws.iter_rows():
        for c in row:
            c.alignment = Alignment(wrap_text=True, vertical="top")
    for col, w in zip("ABCDEFGH", (8, 40, 24, 18, 50, 14, 34, 22)):
        ws.column_dimensions[col].width = w
    wb.save(path)


if __name__ == "__main__":
    open(os.path.join(OUT, "02_جدول_التتبع.md"), "w", encoding="utf-8").write(md())
    xlsx(os.path.join(OUT, "02_جدول_التتبع.xlsx"))
    print(len(ROWS), "rows")
